B.bs9=new A.T(B.bX,["\u0644\u064a\u0633 \u0644\u062f\u064a \u0628\u0639\u062f \u062e\u0637 \u0645\u064f\u0631\u0627\u062c\u064e\u0639 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0645\u062d\u0641\u0648\u0638 \u0644\u0640{region}\u060c \u0644\u0630\u0627 \u0641\u0627\u0644\u062e\u0637\u0648\u0637 \u0623\u0639\u0644\u0627\u0647 \u062a\u0639\u0645\u0644 \u0645\u0646 \u0623\u064a \u0645\u0643\u0627\u0646. \u0627\u062e\u062a\u0631 \u0628\u0644\u062f\u064b\u0627 \u0622\u062e\u0631 \u062a\u062d\u062a \u0627\u0644\u062e\u0637\u0648\u0637 \u0625\u0646 \u0643\u0627\u0646 \u0647\u0630\u0627 \u062e\u0637\u0623\u060c \u0648\u0627\u062d\u062a\u0641\u0638 \u0628\u0631\u0642\u0645 \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0627\u0644\u0645\u062d\u0644\u064a \u0642\u0631\u064a\u0628\u064b\u0627.","{region} \u06a9\u06d2 \u0644\u06cc\u06d2 \u0645\u06cc\u0631\u06d2 \u067e\u0627\u0633 \u0627\u0633 \u0642\u0633\u0645 \u06a9\u06cc \u06a9\u0648\u0626\u06cc \u062c\u0627\u0646\u0686\u06cc \u06c1\u0648\u0626\u06cc \u0644\u0627\u0626\u0646 \u0627\u0628\u06be\u06cc \u0645\u062d\u0641\u0648\u0638 \u0646\u06c1\u06cc\u06ba\u060c \u0627\u0633 \u0644\u06cc\u06d2 \u0627\u0648\u067e\u0631 \u06a9\u06cc \u0644\u0627\u0626\u0646\u06cc\u06ba \u06a9\u06c1\u06cc\u06ba \u0633\u06d2 \u0628\u06be\u06cc \u06a9\u0627\u0645 \u06a9\u0631\u062a\u06cc \u06c1\u06cc\u06ba\u06d4 \u0627\u06af\u0631 \u06cc\u06c1 \u063a\u0644\u0637 \u06c1\u0648 \u062a\u0648 \u0644\u0627\u0626\u0646\u0648\u06ba \u06a9\u06d2 \u0646\u06cc\u0686\u06d2 \u0633\u06d2 \u06a9\u0648\u0626\u06cc \u0627\u0648\u0631 \u0645\u0644\u06a9 \u0686\u0646\u06cc\u06ba\u060c \u0627\u0648\u0631 \u0627\u067e\u0646\u0627 \u0645\u0642\u0627\u0645\u06cc \u0627\u06cc\u0645\u0631\u062c\u0646\u0633\u06cc \u0646\u0645\u0628\u0631 \u0642\u0631\u06cc\u0628 \u0631\u06a9\u06be\u06cc\u06ba\u06d4","{region}-\u098f\u09b0 \u099c\u09a8\u09cd\u09af \u098f\u0987 \u09a7\u09b0\u09a8\u09c7\u09b0 \u0995\u09cb\u09a8\u09cb \u09af\u09be\u099a\u09be\u0987-\u0995\u09b0\u09be \u09b2\u09be\u0987\u09a8 \u098f\u0996\u09a8\u0993 \u0986\u09ae\u09be\u09b0 \u0995\u09be\u099b\u09c7 \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u09a8\u09c7\u0987, \u09a4\u09be\u0987 \u0989\u09aa\u09b0\u09c7\u09b0 \u09b2\u09be\u0987\u09a8\u0997\u09c1\u09b2\u09cb \u09af\u09c7\u0995\u09cb\u09a8\u09cb \u099c\u09be\u09af\u09bc\u0997\u09be \u09a5\u09c7\u0995\u09c7 \u0995\u09be\u099c \u0995\u09b0\u09c7\u0964 \u09ad\u09c1\u09b2 \u09b9\u09b2\u09c7 \u09b2\u09be\u0987\u09a8\u0997\u09c1\u09b2\u09cb\u09b0 \u09a8\u09bf\u099a\u09c7 \u0985\u09a8\u09cd\u09af \u09a6\u09c7\u09b6 \u09ac\u09c7\u099b\u09c7 \u09a8\u09bf\u09a8, \u0986\u09b0 \u09b8\u09cd\u09a5\u09be\u09a8\u09c0\u09af\u09bc \u099c\u09b0\u09c1\u09b0\u09bf \u09a8\u09ae\u09cd\u09ac\u09b0 \u0995\u09be\u099b\u09c7 \u09b0\u09be\u0996\u09c1\u09a8\u0964"],t.w)
B.bsb=new A.T(B.bX,["\u0627\u0644\u062d\u0643\u0645 \u0639\u0644\u0649 \u0623\u064a \u0625\u0646\u0633\u0627\u0646 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u0631\u062d\u0645\u062a\u0647 \u0648\u0627\u0633\u0639\u0629. \u0648\u0644\u0644\u0633\u0624\u0627\u0644 \u0639\u0646 \u062d\u0643\u0645 \u0634\u062e\u0635 \u0628\u0639\u064a\u0646\u0647\u060c \u064a\u064f\u0631\u062c\u0649 \u0633\u0624\u0627\u0644 \u0639\u0627\u0644\u0645 \u0645\u0624\u0647\u0644 \u0648\u062c\u0647\u064b\u0627 \u0644\u0648\u062c\u0647. \u0648\u0625\u0646 \u0643\u0627\u0646 \u0623\u064a \u062c\u0632\u0621 \u0645\u0646 \u0647\u0630\u0627 \u064a\u062e\u0635\u0643\u060c \u0641\u0627\u0644\u062e\u0637\u0648\u0637 \u0623\u0639\u0644\u0627\u0647 \u0645\u0627 \u0632\u0627\u0644\u062a \u0647\u0646\u0627\u060c \u0648\u0631\u0642\u0645 \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0627\u0644\u0645\u062d\u0644\u064a \u062e\u064a\u0627\u0631 \u062f\u0627\u0626\u0645.","\u06a9\u0633\u06cc \u0628\u06be\u06cc \u0634\u062e\u0635 \u06a9\u0627 \u0641\u06cc\u0635\u0644\u06c1 \u0635\u0631\u0641 \u0627\u0644\u0644\u06c1 \u06a9\u06d2 \u0633\u067e\u0631\u062f \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06cc \u0631\u062d\u0645\u062a \u0648\u0633\u06cc\u0639 \u06c1\u06d2\u06d4 \u06a9\u0633\u06cc \u062e\u0627\u0635 \u0634\u062e\u0635 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u062d\u06a9\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0628\u0631\u0627\u06c1\u0650 \u06a9\u0631\u0645 \u06a9\u0633\u06cc \u0627\u06c1\u0644 \u0639\u0627\u0644\u0645 \u0633\u06d2 \u0631\u0648\u0628\u0631\u0648 \u067e\u0648\u0686\u06be\u06cc\u06ba\u06d4 \u0627\u06af\u0631 \u0627\u0633 \u0645\u06cc\u06ba \u0633\u06d2 \u06a9\u0648\u0626\u06cc \u0628\u06be\u06cc \u0628\u0627\u062a \u0622\u067e \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06c1\u06d2 \u062a\u0648 \u0627\u0648\u067e\u0631 \u06a9\u06cc \u0644\u0627\u0626\u0646\u06cc\u06ba \u0627\u0628 \u0628\u06be\u06cc \u0645\u0648\u062c\u0648\u062f \u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u0622\u067e \u06a9\u0627 \u0645\u0642\u0627\u0645\u06cc \u0627\u06cc\u0645\u0631\u062c\u0646\u0633\u06cc \u0646\u0645\u0628\u0631 \u06c1\u0645\u06cc\u0634\u06c1 \u0627\u06cc\u06a9 \u0631\u0627\u0633\u062a\u06c1 \u06c1\u06d2\u06d4","\u0995\u09cb\u09a8\u09cb \u09ae\u09be\u09a8\u09c1\u09b7\u09c7\u09b0 \u09ac\u09bf\u099a\u09be\u09b0 \u098f\u0995\u09ae\u09be\u09a4\u09cd\u09b0 \u0986\u09b2\u09cd\u09b2\u09be\u09b9\u09b0, \u0986\u09b0 \u09a4\u09be\u0981\u09b0 \u09b0\u09b9\u09ae\u09a4 \u09ac\u09bf\u09b6\u09be\u09b2\u0964 \u09a8\u09bf\u09b0\u09cd\u09a6\u09bf\u09b7\u09cd\u099f \u0995\u09be\u09b0\u0993 \u09ac\u09bf\u09b7\u09af\u09bc\u09c7 \u09b0\u09be\u09af\u09bc\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u0985\u09a8\u09c1\u0997\u09cd\u09b0\u09b9 \u0995\u09b0\u09c7 \u09af\u09cb\u0997\u09cd\u09af \u0995\u09cb\u09a8\u09cb \u0986\u09b2\u09c7\u09ae\u0995\u09c7 \u09b8\u09be\u09ae\u09a8\u09be\u09b8\u09be\u09ae\u09a8\u09bf \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09c1\u09a8\u0964 \u098f\u09b0 \u0995\u09cb\u09a8\u09cb \u0985\u0982\u09b6 \u09af\u09a6\u09bf \u0986\u09aa\u09a8\u09be\u09b0 \u09b8\u09ae\u09cd\u09aa\u09b0\u09cd\u0995\u09c7 \u09b9\u09af\u09bc, \u09a4\u09ac\u09c7 \u0989\u09aa\u09b0\u09c7\u09b0 \u09b2\u09be\u0987\u09a8\u0997\u09c1\u09b2\u09cb \u098f\u0996\u09a8\u0993 \u0986\u099b\u09c7, \u0986\u09b0 \u09b8\u09cd\u09a5\u09be\u09a8\u09c0\u09af\u09bc \u099c\u09b0\u09c1\u09b0\u09bf \u09a8\u09ae\u09cd\u09ac\u09b0 \u09b8\u09ac\u09b8\u09ae\u09af\u09bc\u0987 \u098f\u0995\u099f\u09bf \u09aa\u09a5\u0964"],t.w)
B.bsc=new A.T(B.bX,["\u0644\u0644\u062a\u0630\u0643\u064a\u0631 \u0628\u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647: \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645\u060c \u0633\u0648\u0631\u0629 \u0627\u0644\u0632\u0645\u0631\u060c \u0627\u0644\u0622\u064a\u0629 53.","\u0627\u0644\u0644\u06c1 \u06a9\u06cc \u0631\u062d\u0645\u062a \u06a9\u06cc \u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc \u06a9\u06d2 \u0644\u06cc\u06d2: \u0642\u0631\u0622\u0646\u060c \u0633\u0648\u0631\u06c3 \u0627\u0644\u0632\u0645\u0631\u060c \u0622\u06cc\u062a 53\u06d4","\u0986\u09b2\u09cd\u09b2\u09be\u09b9\u09b0 \u09b0\u09b9\u09ae\u09a4\u09c7\u09b0 \u09b8\u09cd\u09ae\u09b0\u09a3\u09c7: \u0995\u09c1\u09b0\u0986\u09a8, \u09b8\u09c2\u09b0\u09be \u0986\u09af-\u09af\u09c1\u09ae\u09be\u09b0, \u0986\u09af\u09bc\u09be\u09a4 53\u0964"],t.w)
