B.b3Z=s(["\u0647\u0627\u062f\u064a \xb7 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0645\u0628\u0627\u0634\u0631 (\u0628\u0636\u0648\u0627\u0628\u0637 \u062d\u0645\u0627\u064a\u0629)","\u06c1\u0627\u062f\u06cc \xb7 \u0644\u0627\u0626\u06cc\u0648 \u0627\u06d2 \u0622\u0626\u06cc (\u062d\u0641\u0627\u0638\u062a\u06cc \u062d\u062f\u0648\u062f \u06a9\u06d2 \u0633\u0627\u062a\u06be)","\u09b9\u09be\u09a6\u09c0 \xb7 \u09b2\u09be\u0987\u09ad \u098f\u0986\u0987 (\u09b8\u09c1\u09b0\u0995\u09cd\u09b7\u09be-\u09b8\u09c0\u09ae\u09be\u09b8\u09b9)"],t.s)
B.blp=s(["\u0647\u0627\u062f\u064a \xb7 \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \u0627\u0644\u0645\u062f\u0645\u062c\u0629","\u06c1\u0627\u062f\u06cc \xb7 \u0628\u0644\u0679 \u0627\u0650\u0646 \u0644\u0627\u0626\u0628\u0631\u06cc\u0631\u06cc","\u09b9\u09be\u09a6\u09c0 \xb7 \u0985\u09a8\u09cd\u09a4\u09b0\u09cd\u09a8\u09bf\u09b0\u09cd\u09ae\u09bf\u09a4 \u09b2\u09be\u0987\u09ac\u09cd\u09b0\u09c7\u09b0\u09bf"],t.s)
