B.Qs=s(["\u0627\u0633\u0623\u0644 \u0647\u0627\u062f\u064a","\u06c1\u0627\u062f\u06cc \u0633\u06d2 \u067e\u0648\u0686\u06be\u06cc\u06ba","\u09b9\u09be\u09a6\u09c0\u0995\u09c7 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09c1\u09a8"],t.s)
B.bi7=s(["\u0627\u0633\u0623\u0644 \u0647\u0627\u062f\u064a \u0623\u064a \u0634\u064a\u0621\u2026","\u06c1\u0627\u062f\u06cc \u0633\u06d2 \u06a9\u0686\u06be \u0628\u06be\u06cc \u067e\u0648\u0686\u06be\u06cc\u06ba\u2026","\u09b9\u09be\u09a6\u09c0\u0995\u09c7 \u09af\u09c7\u0995\u09cb\u09a8\u09cb \u0995\u09bf\u099b\u09c1 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09c1\u09a8\u2026"],t.s)
B.b2z=s(["\u0627\u0633\u0623\u0644 \u0647\u0627\u062f\u064a \u0623\u064a \u0634\u064a\u0621..","\u06c1\u0627\u062f\u06cc \u0633\u06d2 \u06a9\u0686\u06be \u0628\u06be\u06cc \u067e\u0648\u0686\u06be\u06cc\u06ba..","\u09b9\u09be\u09a6\u09c0\u0995\u09c7 \u09af\u09c7\u0995\u09cb\u09a8\u09cb \u0995\u09bf\u099b\u09c1 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09c1\u09a8.."],t.s)
B.aPK=s(["\u0645\u0644\u062e\u0635 \u0643\u064f\u062a\u0628 \u0644\u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0648\u0644\u064a\u0633 \u062a\u0631\u062c\u0645\u0629.","\u06cc\u06c1 \u062e\u0644\u0627\u0635\u06c1 \u0627\u0633 \u0627\u06cc\u067e \u06a9\u06d2 \u0644\u06cc\u06d2 \u0644\u06a9\u06be\u0627 \u06af\u06cc\u0627 \u06c1\u06d2\u060c \u062a\u0631\u062c\u0645\u06c1 \u0646\u06c1\u06cc\u06ba\u06d4","\u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09b2\u09c7\u0996\u09be \u09b8\u09be\u09b0\u09b8\u0982\u0995\u09cd\u09b7\u09c7\u09aa, \u0985\u09a8\u09c1\u09ac\u09be\u09a6 \u09a8\u09af\u09bc\u0964"],t.s)
B.b8q=s(["\u0645\u0642\u062a\u0637\u0641 \u0643\u064f\u062a\u0628 \u0644\u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0648\u0644\u064a\u0633 \u062a\u0631\u062c\u0645\u0629 \u0643\u0627\u0645\u0644\u0629.","\u06cc\u06c1 \u0627\u0642\u062a\u0628\u0627\u0633 \u0627\u0633 \u0627\u06cc\u067e \u06a9\u06d2 \u0644\u06cc\u06d2 \u0644\u06a9\u06be\u0627 \u06af\u06cc\u0627 \u06c1\u06d2\u060c \u0645\u06a9\u0645\u0644 \u062a\u0631\u062c\u0645\u06c1 \u0646\u06c1\u06cc\u06ba\u06d4","\u098f\u0987 \u0985\u09cd\u09af\u09be\u09aa\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09b2\u09c7\u0996\u09be \u0989\u09a6\u09cd\u09a7\u09c3\u09a4\u09be\u0982\u09b6, \u09aa\u09c2\u09b0\u09cd\u09a3 \u0985\u09a8\u09c1\u09ac\u09be\u09a6 \u09a8\u09af\u09bc\u0964"],t.s)
B.b7f=s(["\u0645\u0646 \u0623\u064a\u0646 \u064a\u0623\u062a\u064a \u0647\u0630\u0627","\u06cc\u06c1 \u06a9\u06c1\u0627\u06ba \u0633\u06d2 \u0622\u06cc\u0627","\u098f\u099f\u09bf \u0995\u09cb\u09a5\u09be \u09a5\u09c7\u0995\u09c7 \u098f\u09b8\u09c7\u099b\u09c7"],t.s)
