B.aXg=s(["\u0645\u0644\u0627\u062d\u0638\u0629 \u062d\u0648\u0644 \u0627\u0644\u062f\u0642\u0629","\u062f\u0631\u0633\u062a\u06cc \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0646\u0648\u0679","\u09a8\u09bf\u09b0\u09cd\u09ad\u09c1\u09b2\u09a4\u09be \u09a8\u09bf\u09af\u09bc\u09c7 \u098f\u0995\u099f\u09bf \u09a8\u09cb\u099f"],t.s)
B.aZA=s(["\u062a\u0645 \u0631\u0641\u0636 \u0625\u0630\u0646 \u0627\u0644\u0645\u0648\u0642\u0639. \u0627\u0633\u0645\u062d \u0628\u0647 \u0644\u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0642\u0639 \u0623\u0648 \u0627\u062e\u062a\u0631 \u0645\u062f\u064a\u0646\u062a\u0643 \u0628\u062f\u0644\u064b\u0627 \u0645\u0646 \u0630\u0644\u0643.","\u0645\u0642\u0627\u0645 \u06a9\u06cc \u0627\u062c\u0627\u0632\u062a \u0646\u06c1\u06cc\u06ba \u062f\u06cc \u06af\u0626\u06cc\u06d4 \u0627\u0633 \u0633\u0627\u0626\u0679 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u062c\u0627\u0632\u062a \u062f\u06cc\u06ba \u06cc\u0627 \u0627\u0633 \u06a9\u06cc \u062c\u06af\u06c1 \u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0645\u0646\u062a\u062e\u0628 \u06a9\u0631\u06cc\u06ba\u06d4","\u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8\u09c7\u09b0 \u0985\u09a8\u09c1\u09ae\u09a4\u09bf \u09a6\u09c7\u0993\u09af\u09bc\u09be \u09b9\u09af\u09bc\u09a8\u09bf\u0964 \u098f\u0987 \u09b8\u09be\u0987\u099f\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u0985\u09a8\u09c1\u09ae\u09a4\u09bf \u09a6\u09bf\u09a8, \u0985\u09a5\u09ac\u09be \u09ac\u09b0\u0982 \u0986\u09aa\u09a8\u09be\u09b0 \u09b6\u09b9\u09b0 \u09ac\u09c7\u099b\u09c7 \u09a8\u09bf\u09a8\u0964"],t.s)
B.ba1=s(["\u0627\u0644\u0645\u0648\u0642\u0639 \u0645\u062a\u0648\u0642\u0641 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632. \u0641\u0639\u0651\u0644\u0647 \u0623\u0648 \u0627\u062e\u062a\u0631 \u0645\u062f\u064a\u0646\u062a\u0643 \u0628\u062f\u0644\u064b\u0627 \u0645\u0646 \u0630\u0644\u0643.","\u0627\u0633 \u0622\u0644\u06d2 \u067e\u0631 \u0645\u0642\u0627\u0645 \u0628\u0646\u062f \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u0622\u0646 \u06a9\u0631\u06cc\u06ba \u06cc\u0627 \u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0645\u0646\u062a\u062e\u0628 \u06a9\u0631\u06cc\u06ba\u06d4","\u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8 \u09ac\u09a8\u09cd\u09a7 \u0986\u099b\u09c7\u0964 \u098f\u099f\u09bf \u099a\u09be\u09b2\u09c1 \u0995\u09b0\u09c1\u09a8, \u0985\u09a5\u09ac\u09be \u0986\u09aa\u09a8\u09be\u09b0 \u09b6\u09b9\u09b0 \u09ac\u09c7\u099b\u09c7 \u09a8\u09bf\u09a8\u0964"],t.s)
B.b1G=s(["\u062a\u0639\u0630\u0651\u0631 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0645\u0648\u0642\u0639\u0643. \u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627 \u0623\u0648 \u0627\u062e\u062a\u0631 \u0645\u062f\u064a\u0646\u062a\u0643.","\u0622\u067e \u06a9\u0627 \u0645\u0642\u0627\u0645 \u0645\u0639\u0644\u0648\u0645 \u0646\u06c1\u06cc\u06ba \u06c1\u0648 \u0633\u06a9\u0627\u06d4 \u062f\u0648\u0628\u0627\u0631\u06c1 \u06a9\u0648\u0634\u0634 \u06a9\u0631\u06cc\u06ba \u06cc\u0627 \u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0645\u0646\u062a\u062e\u0628 \u06a9\u0631\u06cc\u06ba\u06d4","\u0986\u09aa\u09a8\u09be\u09b0 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8 \u09aa\u09be\u0993\u09af\u09bc\u09be \u09af\u09be\u09af\u09bc\u09a8\u09bf\u0964 \u0986\u09ac\u09be\u09b0 \u099a\u09c7\u09b7\u09cd\u099f\u09be \u0995\u09b0\u09c1\u09a8, \u0985\u09a5\u09ac\u09be \u0986\u09aa\u09a8\u09be\u09b0 \u09b6\u09b9\u09b0 \u09ac\u09c7\u099b\u09c7 \u09a8\u09bf\u09a8\u0964"],t.s)
B.bhr=s(["\u062a\u0639\u062a\u0645\u062f \u0627\u0644\u0642\u0628\u0644\u0629 \u0639\u0644\u0649 \u0645\u0643\u0627\u0646\u0643\u060c \u0644\u0630\u0627 \u0644\u0627 \u064a\u0638\u0647\u0631 \u0627\u062a\u062c\u0627\u0647 \u062d\u062a\u0649 \u062a\u062d\u062f\u062f \u0645\u0648\u0642\u0639\u0643. \u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u0648\u0642\u0639 \u062c\u0647\u0627\u0632\u0643 \u0623\u0648 \u0645\u062a\u0635\u0641\u062d\u0643 (\u064a\u064f\u0637\u0644\u0628 \u0641\u0642\u0637 \u0639\u0646\u062f \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0632\u0631)\u060c \u0623\u0648 \u0627\u062e\u062a\u0631 \u0645\u062f\u064a\u0646\u062a\u0643 \u0641\u064a \u0645\u0648\u0627\u0642\u064a\u062a \u0627\u0644\u0635\u0644\u0627\u0629. \u062b\u0645 \u064a\u064f\u062d\u0633\u0628 \u0627\u0644\u0627\u062a\u062c\u0627\u0647 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632\u0643.","\u0642\u0628\u0644\u06c1 \u06a9\u06cc \u0633\u0645\u062a \u0622\u067e \u06a9\u06cc \u062c\u06af\u06c1 \u067e\u0631 \u0645\u0646\u062d\u0635\u0631 \u06c1\u06d2\u060c \u0627\u0633 \u0644\u06cc\u06d2 \u0645\u0642\u0627\u0645 \u0637\u06d2 \u06a9\u06cc\u06d2 \u0628\u063a\u06cc\u0631 \u06a9\u0648\u0626\u06cc \u0633\u0645\u062a \u0646\u06c1\u06cc\u06ba \u062f\u06a9\u06be\u0627\u0626\u06cc \u062c\u0627\u062a\u06cc\u06d4 \u0627\u067e\u0646\u06d2 \u0622\u0644\u06d2 \u06cc\u0627 \u0628\u0631\u0627\u0624\u0632\u0631 \u06a9\u0627 \u0645\u0642\u0627\u0645 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u06cc\u06ba (\u0635\u0631\u0641 \u0628\u0679\u0646 \u062f\u0628\u0627\u0646\u06d2 \u067e\u0631 \u067e\u0648\u0686\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2)\u060c \u06cc\u0627 \u0646\u0645\u0627\u0632 \u06a9\u06d2 \u0627\u0648\u0642\u0627\u062a \u0645\u06cc\u06ba \u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0645\u0646\u062a\u062e\u0628 \u06a9\u0631\u06cc\u06ba\u06d4 \u067e\u06be\u0631 \u0633\u0645\u062a \u0622\u067e \u06a9\u06d2 \u0622\u0644\u06d2 \u067e\u0631 \u062d\u0633\u0627\u0628 \u06a9\u06cc \u062c\u0627\u062a\u06cc \u06c1\u06d2\u06d4","\u0995\u09bf\u09ac\u09b2\u09be \u0986\u09aa\u09a8\u09be\u09b0 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8\u09c7\u09b0 \u0993\u09aa\u09b0 \u09a8\u09bf\u09b0\u09cd\u09ad\u09b0 \u0995\u09b0\u09c7, \u09a4\u09be\u0987 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8 \u09a0\u09bf\u0995 \u09a8\u09be \u0995\u09b0\u09be \u09aa\u09b0\u09cd\u09af\u09a8\u09cd\u09a4 \u0995\u09cb\u09a8\u09cb \u09a6\u09bf\u0995 \u09a6\u09c7\u0996\u09be\u09a8\u09cb \u09b9\u09af\u09bc \u09a8\u09be\u0964 \u0986\u09aa\u09a8\u09be\u09b0 \u09a1\u09bf\u09ad\u09be\u0987\u09b8 \u09ac\u09be \u09ac\u09cd\u09b0\u09be\u0989\u099c\u09be\u09b0\u09c7\u09b0 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8 (\u09ac\u09cb\u09a4\u09be\u09ae \u099a\u09be\u09aa\u09b2\u09c7\u0987 \u09b6\u09c1\u09a7\u09c1 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09be \u09b9\u09af\u09bc), \u0985\u09a5\u09ac\u09be \u09a8\u09be\u09ae\u09be\u099c\u09c7\u09b0 \u09b8\u09ae\u09af\u09bc-\u098f \u0986\u09aa\u09a8\u09be\u09b0 \u09b6\u09b9\u09b0 \u09ac\u09c7\u099b\u09c7 \u09a8\u09bf\u09a8\u0964 \u098f\u09b0\u09aa\u09b0 \u09a6\u09bf\u0995\u099f\u09bf \u0986\u09aa\u09a8\u09be\u09b0 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7\u0987 \u09b9\u09bf\u09b8\u09be\u09ac \u0995\u09b0\u09be \u09b9\u09af\u09bc\u0964"],t.s)
B.bfh=s(["\u0623\u0646\u062a \u0645\u062a\u062c\u0647 \u0625\u0644\u0649 \u0627\u0644\u0642\u0628\u0644\u0629","\u0622\u067e \u0642\u0628\u0644\u06c1 \u0631\u062e \u06c1\u06cc\u06ba","\u0986\u09aa\u09a8\u09bf \u0995\u09bf\u09ac\u09b2\u09be\u09ae\u09c1\u0996\u09c0"],t.s)
B.bbS=s(["\u0627\u0646\u0639\u0637\u0641 \u064a\u0645\u064a\u0646\u064b\u0627 {1}\xb0","\u062f\u0627\u0626\u06cc\u06ba \u0645\u0691\u06cc\u06ba {1}\xb0","\u09a1\u09be\u09a8\u09c7 \u0998\u09c1\u09b0\u09c1\u09a8 {1}\xb0"],t.s)
B.aQT=s(["\u0627\u0646\u0639\u0637\u0641 \u064a\u0633\u0627\u0631\u064b\u0627 {1}\xb0","\u0628\u0627\u0626\u06cc\u06ba \u0645\u0691\u06cc\u06ba {1}\xb0","\u09ac\u09be\u09ae\u09c7 \u0998\u09c1\u09b0\u09c1\u09a8 {1}\xb0"],t.s)
B.aHM=s(["\u0627\u0644\u0628\u0648\u0635\u0644\u0629 \u063a\u064a\u0631 \u0645\u0633\u062a\u0642\u0631\u0629. \u0627\u0628\u062a\u0639\u062f \u0639\u0646 \u0627\u0644\u0645\u0639\u0627\u062f\u0646 \u0648\u0627\u0644\u0645\u063a\u0646\u0627\u0637\u064a\u0633 \u0648\u0627\u0644\u0623\u063a\u0637\u064a\u0629 \u0627\u0644\u0645\u0645\u063a\u0646\u0637\u0629\u060c \u062b\u0645 \u062d\u0631\u0651\u0643 \u0627\u0644\u0647\u0627\u062a\u0641 \u0628\u0628\u0637\u0621 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0631\u0642\u0645 8 \u0644\u0625\u0639\u0627\u062f\u0629 \u0645\u0639\u0627\u064a\u0631\u062a\u0647\u0627.","\u0642\u0637\u0628 \u0646\u0645\u0627 \u063a\u06cc\u0631 \u0645\u0633\u062a\u062d\u06a9\u0645 \u06c1\u06d2\u06d4 \u062f\u06be\u0627\u062a\u060c \u0645\u0642\u0646\u0627\u0637\u06cc\u0633 \u0627\u0648\u0631 \u0645\u0642\u0646\u0627\u0637\u06cc\u0633\u06cc \u06a9\u0648\u0631 \u0633\u06d2 \u062f\u0648\u0631 \u06c1\u0679\u06cc\u06ba\u060c \u067e\u06be\u0631 \u0627\u0633\u06d2 \u062f\u0648\u0628\u0627\u0631\u06c1 \u06a9\u06cc\u0644\u06cc\u0628\u0631\u06cc\u0679 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0641\u0648\u0646 \u06a9\u0648 \u0622\u06c1\u0633\u062a\u06c1 \u0622\u06c1\u0633\u062a\u06c1 8 \u06a9\u06cc \u0634\u06a9\u0644 \u0645\u06cc\u06ba \u06af\u06be\u0645\u0627\u0626\u06cc\u06ba\u06d4","\u0995\u09ae\u09cd\u09aa\u09be\u09b8 \u0985\u09b8\u09cd\u09a5\u09bf\u09b0\u0964 \u09a7\u09be\u09a4\u09c1, \u099a\u09c1\u09ae\u09cd\u09ac\u0995 \u0993 \u099a\u09c1\u09ae\u09cd\u09ac\u0995\u09af\u09c1\u0995\u09cd\u09a4 \u0995\u09ad\u09be\u09b0 \u09a5\u09c7\u0995\u09c7 \u09a6\u09c2\u09b0\u09c7 \u09b8\u09b0\u09c1\u09a8, \u09a4\u09be\u09b0\u09aa\u09b0 \u09aa\u09c1\u09a8\u09b0\u09be\u09af\u09bc \u0995\u09cd\u09af\u09be\u09b2\u09bf\u09ac\u09cd\u09b0\u09c7\u099f \u0995\u09b0\u09a4\u09c7 \u09ab\u09cb\u09a8\u099f\u09bf \u09a7\u09c0\u09b0\u09c7 \u09a7\u09c0\u09b0\u09c7 8-\u098f\u09b0 \u0986\u0995\u09be\u09b0\u09c7 \u0998\u09cb\u09b0\u09be\u09a8\u0964"],t.s)
B.bbL=s(["\u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641 \u0627\u0644\u0645\u063a\u0646\u0627\u0637\u064a\u0633\u064a {1} \xb7 \u062a\u0644\u0642\u0627\u0626\u064a\u060c \u0645\u0646 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u063a\u0646\u0627\u0637\u064a\u0633\u064a \u0627\u0644\u0639\u0627\u0644\u0645\u064a \u0644\u0645\u0648\u0642\u0639\u0643","\u0645\u0642\u0646\u0627\u0637\u06cc\u0633\u06cc \u0627\u0646\u062d\u0631\u0627\u0641 {1} \xb7 \u062e\u0648\u062f\u06a9\u0627\u0631\u060c \u0622\u067e \u06a9\u06d2 \u0645\u0642\u0627\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0648\u0631\u0644\u0688 \u0645\u06cc\u06af\u0646\u06cc\u0679\u06a9 \u0645\u0627\u0688\u0644 \u0633\u06d2","\u099a\u09cc\u09ae\u09cd\u09ac\u0995 \u09ac\u09bf\u099a\u09cd\u09af\u09c1\u09a4\u09bf {1} \xb7 \u09b8\u09cd\u09ac\u09af\u09bc\u0982\u0995\u09cd\u09b0\u09bf\u09af\u09bc, \u0986\u09aa\u09a8\u09be\u09b0 \u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u0993\u09af\u09bc\u09be\u09b0\u09cd\u09b2\u09cd\u09a1 \u09ae\u09cd\u09af\u09be\u0997\u09a8\u09c7\u099f\u09bf\u0995 \u09ae\u09a1\u09c7\u09b2 \u09a5\u09c7\u0995\u09c7"],t.s)
B.bkU=s(["\u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641 \u0627\u0644\u0645\u063a\u0646\u0627\u0637\u064a\u0633\u064a {1} \xb7 \u0645\u0646 \u0627\u062e\u062a\u064a\u0627\u0631\u0643 (\u0627\u0644\u063a\u0631\u0628 \u0633\u0627\u0644\u0628)","\u0645\u0642\u0646\u0627\u0637\u06cc\u0633\u06cc \u0627\u0646\u062d\u0631\u0627\u0641 {1} \xb7 \u0622\u067e \u06a9\u0627 \u0637\u06d2 \u06a9\u0631\u062f\u06c1 (\u0645\u063a\u0631\u0628 \u0645\u0646\u0641\u06cc \u06c1\u06d2)","\u099a\u09cc\u09ae\u09cd\u09ac\u0995 \u09ac\u09bf\u099a\u09cd\u09af\u09c1\u09a4\u09bf {1} \xb7 \u0986\u09aa\u09a8\u09be\u09b0 \u09a0\u09bf\u0995 \u0995\u09b0\u09be (\u09aa\u09b6\u09cd\u099a\u09bf\u09ae \u098b\u09a3\u09be\u09a4\u09cd\u09ae\u0995)"],t.s)
B.bme=s(["\u0635\u062f\u0631 \u0647\u0630\u0627 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0644\u0644\u0641\u062a\u0631\u0629 2025\u20132030 \u0648\u0627\u0644\u064a\u0648\u0645 \u062e\u0627\u0631\u062c \u0647\u0630\u0647 \u0627\u0644\u0641\u062a\u0631\u0629\u060c \u0644\u0630\u0627 \u0642\u062f \u064a\u0643\u0648\u0646 \u0627\u0644\u0631\u0642\u0645 \u063a\u064a\u0631 \u062f\u0642\u064a\u0642. \u064a\u0645\u0643\u0646\u0643 \u0636\u0628\u0637 \u0631\u0642\u0645\u0643.","\u06cc\u06c1 \u0645\u0627\u0688\u0644 2025\u20132030 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062c\u0627\u0631\u06cc \u06c1\u0648\u0627 \u062a\u06be\u0627 \u0627\u0648\u0631 \u0622\u062c \u0627\u0633 \u0645\u062f\u062a \u0633\u06d2 \u0628\u0627\u06c1\u0631 \u06c1\u06d2\u060c \u0627\u0633 \u0644\u06cc\u06d2 \u0639\u062f\u062f \u062f\u0631\u0633\u062a \u0646\u06c1 \u06c1\u0648 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4 \u0622\u067e \u0627\u067e\u0646\u0627 \u0639\u062f\u062f \u0645\u0642\u0631\u0631 \u06a9\u0631 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u098f\u0987 \u09ae\u09a1\u09c7\u09b2 2025\u20132030 \u09b8\u09be\u09b2\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09aa\u09cd\u09b0\u0995\u09be\u09b6\u09bf\u09a4 \u098f\u09ac\u0982 \u0986\u099c \u09b8\u09c7\u0987 \u09b8\u09ae\u09af\u09bc\u09c7\u09b0 \u09ac\u09be\u0987\u09b0\u09c7, \u09a4\u09be\u0987 \u09b8\u0982\u0996\u09cd\u09af\u09be\u099f\u09bf \u09ad\u09c1\u09b2 \u09b9\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u0964 \u0986\u09aa\u09a8\u09bf \u09a8\u09bf\u099c\u09c7\u09b0 \u09b8\u0982\u0996\u09cd\u09af\u09be \u09a6\u09bf\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u09a8\u0964"],t.s)
B.aWM=s(["\u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641 1\xb0 \u063a\u0631\u0628\u064b\u0627 \u0623\u0643\u062b\u0631","\u0627\u0646\u062d\u0631\u0627\u0641 1\xb0 \u0645\u0632\u06cc\u062f \u0645\u063a\u0631\u0628","\u09ac\u09bf\u099a\u09cd\u09af\u09c1\u09a4\u09bf \u0986\u09b0\u0993 1\xb0 \u09aa\u09b6\u09cd\u099a\u09bf\u09ae\u09c7"],t.s)
B.bg6=s(["\u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641 1\xb0 \u0634\u0631\u0642\u064b\u0627 \u0623\u0643\u062b\u0631","\u0627\u0646\u062d\u0631\u0627\u0641 1\xb0 \u0645\u0632\u06cc\u062f \u0645\u0634\u0631\u0642","\u09ac\u09bf\u099a\u09cd\u09af\u09c1\u09a4\u09bf \u0986\u09b0\u0993 1\xb0 \u09aa\u09c2\u09b0\u09cd\u09ac\u09c7"],t.s)
B.b54=s(["\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0644\u0642\u0627\u0626\u064a","\u062e\u0648\u062f\u06a9\u0627\u0631 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u06cc\u06ba","\u09b8\u09cd\u09ac\u09af\u09bc\u0982\u0995\u09cd\u09b0\u09bf\u09af\u09bc \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8"],t.s)
B.aOR=s(["\u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u0628\u0648\u0635\u0644\u0629","\u0642\u0637\u0628 \u0646\u0645\u0627 \u0628\u0646\u062f \u06a9\u0631\u06cc\u06ba","\u0995\u09ae\u09cd\u09aa\u09be\u09b8 \u09ac\u09a8\u09cd\u09a7 \u0995\u09b0\u09c1\u09a8"],t.s)
B.b0n=s(["\u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641: \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u063a\u0646\u0627\u0637\u064a\u0633\u064a \u0627\u0644\u0639\u0627\u0644\u0645\u064a 2025\u060c \u0645\u0646 \u0625\u0639\u062f\u0627\u062f NOAA/NCEI \u0648\u0627\u0644\u0645\u0633\u062d \u0627\u0644\u062c\u064a\u0648\u0644\u0648\u062c\u064a \u0627\u0644\u0628\u0631\u064a\u0637\u0627\u0646\u064a.","\u0627\u0646\u062d\u0631\u0627\u0641: \u0648\u0631\u0644\u0688 \u0645\u06cc\u06af\u0646\u06cc\u0679\u06a9 \u0645\u0627\u0688\u0644 2025\u060c \u062c\u0633\u06d2 NOAA/NCEI \u0627\u0648\u0631 \u0628\u0631\u0679\u0634 \u062c\u06cc\u0648\u0644\u0648\u062c\u06cc\u06a9\u0644 \u0633\u0631\u0648\u06d2 \u0646\u06d2 \u062a\u06cc\u0627\u0631 \u06a9\u06cc\u0627\u06d4","\u09ac\u09bf\u099a\u09cd\u09af\u09c1\u09a4\u09bf: \u0993\u09af\u09bc\u09be\u09b0\u09cd\u09b2\u09cd\u09a1 \u09ae\u09cd\u09af\u09be\u0997\u09a8\u09c7\u099f\u09bf\u0995 \u09ae\u09a1\u09c7\u09b2 2025, NOAA/NCEI \u0993 \u09ac\u09cd\u09b0\u09bf\u099f\u09bf\u09b6 \u099c\u09bf\u0993\u09b2\u099c\u09bf\u0995\u09cd\u09af\u09be\u09b2 \u09b8\u09be\u09b0\u09cd\u09ad\u09c7 \u09a4\u09c8\u09b0\u09bf \u0995\u09b0\u09c7\u099b\u09c7\u0964"],t.s)
B.aV7=s(["\u0627\u0644\u0628\u0648\u0635\u0644\u0629 \u0627\u0644\u062d\u064a\u0629 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0647\u0646\u0627 \u2014 \u0627\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0642\u0631\u0635 \u0648\u0627\u0644\u0637\u0631\u064a\u0642\u062a\u064a\u0646 \u0623\u062f\u0646\u0627\u0647.","\u0644\u0627\u0626\u06cc\u0648 \u0642\u0637\u0628 \u0646\u0645\u0627 \u06cc\u06c1\u0627\u06ba \u062f\u0633\u062a\u06cc\u0627\u0628 \u0646\u06c1\u06cc\u06ba \u2014 \u0688\u0627\u0626\u0644 \u0627\u0648\u0631 \u0646\u06cc\u0686\u06d2 \u062f\u06cc\u06d2 \u062f\u0648 \u0637\u0631\u06cc\u0642\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u06cc\u06ba\u06d4","\u09b2\u09be\u0987\u09ad \u0995\u09ae\u09cd\u09aa\u09be\u09b8 \u098f\u0996\u09be\u09a8\u09c7 \u09a8\u09c7\u0987 \u2014 \u09a1\u09be\u09af\u09bc\u09be\u09b2 \u0993 \u09a8\u09bf\u099a\u09c7\u09b0 \u09a6\u09c1\u099f\u09bf \u09aa\u09a6\u09cd\u09a7\u09a4\u09bf \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8\u0964"],t.s)
B.aLj=s(["\u062c\u0627\u0631\u064d \u0627\u0644\u0628\u062f\u0621\u2026","\u0634\u0631\u0648\u0639 \u06c1\u0648 \u0631\u06c1\u0627 \u06c1\u06d2\u2026","\u09b6\u09c1\u09b0\u09c1 \u09b9\u099a\u09cd\u099b\u09c7\u2026"],t.s)
B.b2h=s(["\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0628\u0648\u0635\u0644\u0629 \u0627\u0644\u062d\u064a\u0629","\u0644\u0627\u0626\u06cc\u0648 \u0642\u0637\u0628 \u0646\u0645\u0627 \u0634\u0631\u0648\u0639 \u06a9\u0631\u06cc\u06ba","\u09b2\u09be\u0987\u09ad \u0995\u09ae\u09cd\u09aa\u09be\u09b8 \u099a\u09be\u09b2\u09c1 \u0995\u09b0\u09c1\u09a8"],t.s)
B.bdz=s(["\u062a\u0645 \u0631\u0641\u0636 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u062d\u0631\u0643\u0629. \u0627\u0633\u0645\u062d \u0628\u0647 \u0644\u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0642\u0639 \u0641\u064a \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u062a\u0635\u0641\u062d \u062b\u0645 \u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.","\u062d\u0631\u06a9\u062a \u062a\u06a9 \u0631\u0633\u0627\u0626\u06cc \u0646\u06c1\u06cc\u06ba \u062f\u06cc \u06af\u0626\u06cc\u06d4 \u0628\u0631\u0627\u0624\u0632\u0631 \u06a9\u06cc \u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u0645\u06cc\u06ba \u0627\u0633 \u0633\u0627\u0626\u0679 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u062c\u0627\u0632\u062a \u062f\u06cc\u06ba\u060c \u067e\u06be\u0631 \u062f\u0648\u0628\u0627\u0631\u06c1 \u06a9\u0648\u0634\u0634 \u06a9\u0631\u06cc\u06ba\u06d4","\u09ae\u09cb\u09b6\u09a8 \u0985\u09cd\u09af\u09be\u0995\u09cd\u09b8\u09c7\u09b8 \u09a6\u09c7\u0993\u09af\u09bc\u09be \u09b9\u09af\u09bc\u09a8\u09bf\u0964 \u09ac\u09cd\u09b0\u09be\u0989\u099c\u09be\u09b0\u09c7\u09b0 \u09b8\u09c7\u099f\u09bf\u0982\u09b8\u09c7 \u098f\u0987 \u09b8\u09be\u0987\u099f\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u0985\u09a8\u09c1\u09ae\u09a4\u09bf \u09a6\u09bf\u09a8, \u09a4\u09be\u09b0\u09aa\u09b0 \u0986\u09ac\u09be\u09b0 \u099a\u09c7\u09b7\u09cd\u099f\u09be \u0995\u09b0\u09c1\u09a8\u0964"],t.s)
B.bmd=s(["\u0644\u0645 \u062a\u0635\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0645\u0646 \u0627\u0644\u0628\u0648\u0635\u0644\u0629. \u064a\u062d\u062a\u0627\u062c \u0647\u0630\u0627 \u0625\u0644\u0649 \u0647\u0627\u062a\u0641 \u0628\u0647 \u0645\u0633\u062a\u0634\u0639\u0631 \u0628\u0648\u0635\u0644\u0629 (\u0648\u0635\u0641\u062d\u0629 https \u0641\u064a \u0627\u0644\u0645\u062a\u0635\u0641\u062d)\u061b \u0648\u0623\u062c\u0647\u0632\u0629 \u0633\u0637\u062d \u0627\u0644\u0645\u0643\u062a\u0628 \u0644\u0627 \u062a\u0645\u0644\u0643\u0647 \u0639\u0627\u062f\u0629.","\u0642\u0637\u0628 \u0646\u0645\u0627 \u06a9\u0627 \u06a9\u0648\u0626\u06cc \u0688\u06cc\u0679\u0627 \u0646\u06c1\u06cc\u06ba \u0622\u06cc\u0627\u06d4 \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0642\u0637\u0628 \u0646\u0645\u0627 \u0633\u06cc\u0646\u0633\u0631 \u0648\u0627\u0644\u0627 \u0641\u0648\u0646 (\u0627\u0648\u0631 \u0628\u0631\u0627\u0624\u0632\u0631 \u0645\u06cc\u06ba https \u0635\u0641\u062d\u06c1) \u0686\u0627\u06c1\u06cc\u06d2\u061b \u0688\u06cc\u0633\u06a9 \u0679\u0627\u067e \u0645\u06cc\u06ba \u0639\u0645\u0648\u0645\u0627\u064b \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627\u06d4","\u0995\u09ae\u09cd\u09aa\u09be\u09b8\u09c7\u09b0 \u0995\u09cb\u09a8\u09cb \u09a1\u09c7\u099f\u09be \u0986\u09b8\u09c7\u09a8\u09bf\u0964 \u098f\u09b0 \u099c\u09a8\u09cd\u09af \u0995\u09ae\u09cd\u09aa\u09be\u09b8 \u09b8\u09c7\u09a8\u09cd\u09b8\u09b0\u09b8\u09b9 \u09ab\u09cb\u09a8 (\u098f\u09ac\u0982 \u09ac\u09cd\u09b0\u09be\u0989\u099c\u09be\u09b0\u09c7 https \u09aa\u09be\u09a4\u09be) \u09b2\u09be\u0997\u09c7; \u09a1\u09c7\u09b8\u09cd\u0995\u099f\u09aa\u09c7 \u09b8\u09be\u09a7\u09be\u09b0\u09a3\u09a4 \u09a5\u09be\u0995\u09c7 \u09a8\u09be\u0964"],t.s)
