B.aPR=s(["\u0627\u062e\u062a\u0631 \u0644\u063a\u062a\u0643. \u062a\u063a\u0637\u064a \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u063a\u0627\u0644\u064a\u0629 \u0648\u0627\u0644\u0623\u0631\u062f\u064a\u0629 \u0627\u0644\u0622\u0646 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0648\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u0629. \u0643\u0644 \u062a\u0631\u062c\u0645\u0629 \u0645\u0633\u0648\u062f\u0629 \u0622\u0644\u064a\u0629 \u0644\u0645 \u064a\u0631\u0627\u062c\u0639\u0647\u0627 \u0645\u062a\u062d\u062f\u062b \u0623\u0635\u0644\u064a \u0628\u0639\u062f. \u062a\u0628\u0642\u0649 \u0627\u0644\u062f\u0631\u0648\u0633 \u0648\u0627\u0644\u0642\u0635\u0635 \u0648\u0625\u062c\u0627\u0628\u0627\u062a \u0647\u0627\u062f\u064a \u0628\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629. \u0627\u0644\u0644\u063a\u0627\u062a \u0627\u0644\u0623\u062e\u0631\u0649 \u063a\u064a\u0631 \u0645\u062a\u0631\u062c\u0645\u0629 \u0628\u0639\u062f.","\u0627\u067e\u0646\u06cc \u0632\u0628\u0627\u0646 \u0686\u0646\u06cc\u06ba\u06d4 \u0639\u0631\u0628\u06cc\u060c \u0628\u0646\u06af\u0644\u06c1 \u0627\u0648\u0631 \u0627\u0631\u062f\u0648 \u0627\u0628 \u0627\u06c1\u0645 \u0627\u0633\u06a9\u0631\u06cc\u0646\u0648\u06ba \u0627\u0648\u0631 \u0633\u067e\u0648\u0631\u0679 \u0648 \u062d\u0641\u0627\u0638\u062a \u06a9\u06d2 \u0627\u0644\u0641\u0627\u0638 \u06a9\u0627 \u0627\u062d\u0627\u0637\u06c1 \u06a9\u0631\u062a\u06cc \u06c1\u06cc\u06ba\u06d4 \u06c1\u0631 \u062a\u0631\u062c\u0645\u06c1 \u0645\u0634\u06cc\u0646 \u0633\u06d2 \u062a\u06cc\u0627\u0631 \u06a9\u0631\u062f\u06c1 \u0645\u0633\u0648\u062f\u06c1 \u06c1\u06d2 \u062c\u0633\u06d2 \u0627\u0628\u06be\u06cc \u06a9\u0633\u06cc \u0645\u0627\u062f\u0631\u06cc \u0632\u0628\u0627\u0646 \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0646\u06d2 \u0646\u06c1\u06cc\u06ba \u062f\u06cc\u06a9\u06be\u0627\u06d4 \u0627\u0633\u0628\u0627\u0642\u060c \u06a9\u06c1\u0627\u0646\u06cc\u0627\u06ba \u0627\u0648\u0631 \u06c1\u0627\u062f\u06cc \u06a9\u06d2 \u062c\u0648\u0627\u0628\u0627\u062a \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u0631\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u062f\u0648\u0633\u0631\u06cc \u0632\u0628\u0627\u0646\u0648\u06ba \u06a9\u0627 \u062a\u0631\u062c\u0645\u06c1 \u0627\u0628\u06be\u06cc \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u0627\u06d4","\u0986\u09aa\u09a8\u09be\u09b0 \u09ad\u09be\u09b7\u09be \u09ac\u09c7\u099b\u09c7 \u09a8\u09bf\u09a8\u0964 \u0986\u09b0\u09ac\u09bf, \u09ac\u09be\u0982\u09b2\u09be \u0993 \u0989\u09b0\u09cd\u09a6\u09c1 \u098f\u0996\u09a8 \u09aa\u09cd\u09b0\u09a7\u09be\u09a8 \u09aa\u09b0\u09cd\u09a6\u09be\u0997\u09c1\u09b2\u09cb \u098f\u09ac\u0982 \u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be \u0993 \u09a8\u09bf\u09b0\u09be\u09aa\u09a4\u09cd\u09a4\u09be\u09b0 \u09b6\u09ac\u09cd\u09a6\u099a\u09af\u09bc\u09a8 \u0995\u09ad\u09be\u09b0 \u0995\u09b0\u09c7\u0964 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u0985\u09a8\u09c1\u09ac\u09be\u09a6 \u098f\u0995\u099f\u09bf \u09af\u09be\u09a8\u09cd\u09a4\u09cd\u09b0\u09bf\u0995 \u0996\u09b8\u09a1\u09bc\u09be, \u09af\u09be \u098f\u0996\u09a8\u0993 \u0995\u09cb\u09a8\u09cb \u09ae\u09be\u09a4\u09c3\u09ad\u09be\u09b7\u09c0 \u09af\u09be\u099a\u09be\u0987 \u0995\u09b0\u09c7\u09a8\u09a8\u09bf\u0964 \u09aa\u09be\u09a0, \u0997\u09b2\u09cd\u09aa \u0993 \u09b9\u09be\u09a6\u09c0\u09b0 \u0989\u09a4\u09cd\u09a4\u09b0 \u0987\u0982\u09b0\u09c7\u099c\u09bf\u09a4\u09c7\u0987 \u09a5\u09be\u0995\u09c7\u0964 \u0985\u09a8\u09cd\u09af \u09ad\u09be\u09b7\u09be\u0997\u09c1\u09b2\u09cb \u098f\u0996\u09a8\u0993 \u0985\u09a8\u09c2\u09a6\u09bf\u09a4 \u09b9\u09af\u09bc\u09a8\u09bf\u0964"],t.s)
B.beh=s(["\u062f\u0648\u0646 \u0627\u062a\u0635\u0627\u0644","\u0622\u0641 \u0644\u0627\u0626\u0646","\u0985\u09ab\u09b2\u09be\u0987\u09a8"],t.s)
B.bnC=s(["\u062a\u0644\u0627\u0648\u0627\u062a \u0648\u0642\u0635\u0635 \u0648\u0623\u062f\u0644\u0629 \u0648\u0623\u062f\u0639\u064a\u0629 \u0644\u062a\u0628\u0642\u0649 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632. \u0646\u0632\u0651\u0644 \u0643\u0644 \u0634\u064a\u0621\u060c \u0623\u0648 \u0633\u0648\u0631\u0629 \u0623\u0648 \u062c\u0632\u0621\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0641\u064a \u0643\u0644 \u0645\u0631\u0629.","\u062a\u0644\u0627\u0648\u062a \u06a9\u06cc \u0622\u0688\u06cc\u0648\u060c \u06a9\u06c1\u0627\u0646\u06cc\u0627\u06ba\u060c \u0631\u06c1\u0646\u0645\u0627 \u0627\u0648\u0631 \u062f\u0639\u0627\u0626\u06cc\u06ba \u0627\u0633 \u0622\u0644\u06d2 \u067e\u0631 \u0631\u06a9\u06be\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2\u06d4 \u0633\u0628 \u06a9\u0686\u06be \u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u06a9\u0631\u06cc\u06ba\u060c \u06cc\u0627 \u0627\u06cc\u06a9 \u0648\u0642\u062a \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0633\u0648\u0631\u062a \u06cc\u0627 \u067e\u0627\u0631\u06c1\u06d4","\u09a4\u09bf\u09b2\u09be\u0993\u09af\u09bc\u09be\u09a4\u09c7\u09b0 \u0985\u09a1\u09bf\u0993, \u0997\u09b2\u09cd\u09aa, \u09a8\u09bf\u09b0\u09cd\u09a6\u09c7\u09b6\u09bf\u0995\u09be \u0993 \u09a6\u09cb\u09af\u09bc\u09be \u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7 \u09b0\u09be\u0996\u09be\u09b0 \u099c\u09a8\u09cd\u09af\u0964 \u09b8\u09ac \u09a1\u09be\u0989\u09a8\u09b2\u09cb\u09a1 \u0995\u09b0\u09c1\u09a8, \u0985\u09a5\u09ac\u09be \u098f\u0995\u09ac\u09be\u09b0\u09c7 \u098f\u0995\u099f\u09bf \u09b8\u09c2\u09b0\u09be \u09ac\u09be \u09aa\u09be\u09b0\u09be\u0964"],t.s)
