B.b0G=s(["\u0644\u0627 \u062a\u0638\u0647\u0631 \u0625\u0644\u0627 \u0639\u0646\u062f \u0641\u062a\u062d \u0647\u0627\u062f\u064a \u0623\u0648 \u0648\u0635\u064a\u0629. \u0648\u0644\u0627 \u062a\u0643\u0648\u0646 \u0625\u0634\u0639\u0627\u0631\u064b\u0627 \u0623\u0628\u062f\u064b\u0627\u060c \u0648\u0644\u0627 \u062a\u0631\u062a\u0628\u0637 \u0628\u0627\u0644\u0646\u0634\u0627\u0637. \u064a\u064f\u062e\u0632\u064e\u0651\u0646 \u0641\u0642\u0637 \u064a\u0648\u0645 \u0622\u062e\u0631 \u0633\u0624\u0627\u0644 \u0648\u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f.","\u06cc\u06c1 \u0635\u0631\u0641 \u062a\u0628 \u0622\u062a\u0627 \u06c1\u06d2 \u062c\u0628 \u0622\u067e \u06c1\u0627\u062f\u06cc \u06cc\u0627 \u0648\u0635\u06cc\u06c1 \u06a9\u06be\u0648\u0644\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u06cc\u06c1 \u06a9\u0628\u06be\u06cc \u0646\u0648\u0679\u06cc\u0641\u06a9\u06cc\u0634\u0646 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627 \u0627\u0648\u0631 \u06a9\u0628\u06be\u06cc \u0633\u0631\u06af\u0631\u0645\u06cc \u0633\u06d2 \u062c\u0691\u0627 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627\u06d4 \u0635\u0631\u0641 \u0622\u062e\u0631\u06cc \u0628\u0627\u0631 \u067e\u0648\u0686\u06be\u0646\u06d2 \u06a9\u0627 \u062f\u0646 \u0627\u0648\u0631 \u06cc\u06c1 \u062a\u0631\u062a\u06cc\u0628 \u0645\u062d\u0641\u0648\u0638 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4","\u098f\u099f\u09bf \u09b6\u09c1\u09a7\u09c1 \u09a4\u0996\u09a8\u0987 \u0986\u09b8\u09c7 \u09af\u0996\u09a8 \u0986\u09aa\u09a8\u09bf \u09b9\u09be\u09a6\u09c0 \u09ac\u09be \u0993\u09af\u09bc\u09be\u09b8\u09bf\u09af\u09bc\u09be \u0996\u09cb\u09b2\u09c7\u09a8\u0964 \u098f\u099f\u09bf \u0995\u0996\u09a8\u0993 \u09a8\u09cb\u099f\u09bf\u09ab\u09bf\u0995\u09c7\u09b6\u09a8 \u09a8\u09af\u09bc, \u098f\u09ac\u0982 \u0995\u0996\u09a8\u0993 \u0995\u09be\u09b0\u09cd\u09af\u0995\u09b2\u09be\u09aa\u09c7\u09b0 \u09b8\u09be\u09a5\u09c7 \u09af\u09c1\u0995\u09cd\u09a4 \u09a8\u09af\u09bc\u0964 \u09b6\u09c1\u09a7\u09c1 \u09b6\u09c7\u09b7 \u0995\u09ac\u09c7 \u099c\u09bf\u099c\u09cd\u099e\u09be\u09b8\u09be \u0995\u09b0\u09be \u09b9\u09af\u09bc\u09c7\u099b\u09bf\u09b2 \u09b8\u09c7\u0987 \u09a6\u09bf\u09a8 \u098f\u09ac\u0982 \u098f\u0987 \u09b8\u09c7\u099f\u09bf\u0982 \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u09a5\u09be\u0995\u09c7\u0964"],t.s)
B.aPX=s(["\u0645\u0627 \u064a\u062a\u0630\u0643\u0631\u0647 \u0647\u0627\u062f\u064a","\u06c1\u0627\u062f\u06cc \u06a9\u06cc\u0627 \u06cc\u0627\u062f \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2","\u09b9\u09be\u09a6\u09c0 \u0995\u09c0 \u09ae\u09a8\u09c7 \u09b0\u09be\u0996\u09c7"],t.s)
B.aVI=s(["\u062f\u0639 \u0647\u0627\u062f\u064a \u064a\u062a\u0630\u0643\u0631 \u0645\u0627 \u0623\u062e\u0628\u0631\u0647 \u0628\u0647","\u06c1\u0627\u062f\u06cc \u06a9\u0648 \u0648\u06c1 \u0628\u0627\u062a\u06cc\u06ba \u06cc\u0627\u062f \u0631\u06a9\u06be\u0646\u06d2 \u062f\u06cc\u06ba \u062c\u0648 \u0645\u06cc\u06ba \u0627\u0633\u06d2 \u0628\u062a\u0627\u062a\u0627 \u06c1\u0648\u06ba","\u09b9\u09be\u09a6\u09c0\u0995\u09c7 \u0986\u09ae\u09be\u09b0 \u09ac\u09b2\u09be \u0995\u09a5\u09be \u09ae\u09a8\u09c7 \u09b0\u09be\u0996\u09a4\u09c7 \u09a6\u09bf\u09a8"],t.s)
B.aQf=s(["\u0645\u062a\u0648\u0642\u0641 \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u064b\u0627. \u0641\u0642\u0637 \u0645\u0627 \u062a\u0637\u0644\u0628 \u0645\u0646\u0647 \u062a\u0630\u0643\u0631\u0647\u060c \u0648\u064a\u064f\u062d\u0641\u0638 \u0645\u0634\u0641\u0631\u064b\u0627 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632.","\u0628\u0637\u0648\u0631 \u0688\u06cc\u0641\u0627\u0644\u0679 \u0628\u0646\u062f\u06d4 \u0635\u0631\u0641 \u0648\u06c1\u06cc \u062c\u0648 \u0622\u067e \u06cc\u0627\u062f \u0631\u06a9\u06be\u0646\u06d2 \u06a9\u0648 \u06a9\u06c1\u06cc\u06ba\u060c \u0627\u0633 \u0622\u0644\u06d2 \u067e\u0631 \u0627\u0646\u06a9\u0631\u067e\u0679 \u06a9\u0631 \u06a9\u06d2 \u0631\u06a9\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4","\u09a1\u09bf\u09ab\u09b2\u09cd\u099f\u09c7 \u09ac\u09a8\u09cd\u09a7\u0964 \u09b6\u09c1\u09a7\u09c1 \u09af\u09be \u09ae\u09a8\u09c7 \u09b0\u09be\u0996\u09a4\u09c7 \u09ac\u09b2\u09ac\u09c7\u09a8, \u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7 \u098f\u09a8\u0995\u09cd\u09b0\u09bf\u09aa\u09cd\u099f \u0995\u09b0\u09c7 \u09b0\u09be\u0996\u09be \u09b9\u09af\u09bc\u0964"],t.s)
B.aOM=s(["\u062d\u0630\u0641 \u0645\u0627 \u064a\u0639\u0631\u0641\u0647 \u0647\u0627\u062f\u064a\u061f","\u062c\u0648 \u06c1\u0627\u062f\u06cc \u062c\u0627\u0646\u062a\u0627 \u06c1\u06d2 \u0648\u06c1 \u062d\u0630\u0641 \u06a9\u0631\u06cc\u06ba\u061f","\u09b9\u09be\u09a6\u09c0 \u09af\u09be \u099c\u09be\u09a8\u09c7 \u09a4\u09be \u09ae\u09c1\u099b\u09ac\u09c7\u09a8?"],t.s)
B.bbU=s(["\u064a\u0645\u0643\u0646\u0643 \u0625\u0628\u0642\u0627\u0621 \u0645\u0627 \u062d\u064f\u0641\u0638 \u0623\u0648 \u062d\u0630\u0641\u0647 \u0627\u0644\u0622\u0646.","\u0622\u067e \u062c\u0648 \u0645\u062d\u0641\u0648\u0638 \u06c1\u06d2 \u0627\u0633\u06d2 \u0631\u06a9\u06be \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba \u06cc\u0627 \u0627\u0628\u06be\u06cc \u062d\u0630\u0641 \u06a9\u0631 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u09af\u09be \u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u0986\u099b\u09c7 \u09a4\u09be \u09b0\u09be\u0996\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u09a8, \u09ac\u09be \u098f\u0996\u09a8\u0987 \u09ae\u09c1\u099b\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u09a8\u0964"],t.s)
B.aRf=s(["\u0645\u0627 \u064a\u0639\u0631\u0641\u0647 \u0647\u0627\u062f\u064a \u0639\u0646\u064a","\u06c1\u0627\u062f\u06cc \u0645\u06cc\u0631\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u062c\u0627\u0646\u062a\u0627 \u06c1\u06d2","\u09b9\u09be\u09a6\u09c0 \u0986\u09ae\u09be\u09b0 \u09b8\u09ae\u09cd\u09aa\u09b0\u09cd\u0995\u09c7 \u0995\u09c0 \u099c\u09be\u09a8\u09c7"],t.s)
B.b85=s(["\u0627\u0639\u0631\u0636 \u0623\u0648 \u0639\u062f\u0651\u0644 \u0623\u0648 \u0627\u062d\u0630\u0641 \u0639\u0646\u0635\u0631\u064b\u0627 \u0623\u0648 \u0627\u062d\u0630\u0641 \u0627\u0644\u0643\u0644 \u0623\u0648 \u0635\u062f\u0651\u0631. \u0644\u0627 \u064a\u062d\u062a\u0641\u0638 \u0647\u0627\u062f\u064a \u0628\u0623\u064a \u0634\u064a\u0621 \u0639\u0646 \u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0623\u0648 \u0627\u0644\u0635\u062d\u0629 \u0623\u0648 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0645\u062e\u062f\u0631\u0629 \u062d\u062a\u0649 \u0644\u0648 \u0637\u064f\u0644\u0628 \u0645\u0646\u0647.","\u062f\u06cc\u06a9\u06be\u06cc\u06ba\u060c \u062a\u0631\u0645\u06cc\u0645 \u06a9\u0631\u06cc\u06ba\u060c \u0627\u06cc\u06a9 \u0686\u06cc\u0632 \u062d\u0630\u0641 \u06a9\u0631\u06cc\u06ba\u060c \u0633\u0628 \u062d\u0630\u0641 \u06a9\u0631\u06cc\u06ba\u060c \u06cc\u0627 \u0628\u0631\u0622\u0645\u062f \u06a9\u0631\u06cc\u06ba\u06d4 \u06c1\u0627\u062f\u06cc \u062d\u0641\u0627\u0638\u062a\u060c \u0635\u062d\u062a \u06cc\u0627 \u0646\u0634\u06c1 \u0622\u0648\u0631 \u0627\u0634\u06cc\u0627 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06a9\u0628\u06be\u06cc \u06a9\u0686\u06be \u0646\u06c1\u06cc\u06ba \u0631\u06a9\u06be\u062a\u0627\u060c \u0686\u0627\u06c1\u06d2 \u06a9\u06c1\u0627 \u062c\u0627\u0626\u06d2\u06d4","\u09a6\u09c7\u0996\u09c1\u09a8, \u09b8\u09ae\u09cd\u09aa\u09be\u09a6\u09a8\u09be \u0995\u09b0\u09c1\u09a8, \u098f\u0995\u099f\u09bf \u09ae\u09c1\u099b\u09c1\u09a8, \u09b8\u09ac \u09ae\u09c1\u099b\u09c1\u09a8, \u09ac\u09be \u098f\u0995\u09cd\u09b8\u09aa\u09cb\u09b0\u09cd\u099f \u0995\u09b0\u09c1\u09a8\u0964 \u09b9\u09be\u09a6\u09c0 \u09a8\u09bf\u09b0\u09be\u09aa\u09a4\u09cd\u09a4\u09be, \u09b8\u09cd\u09ac\u09be\u09b8\u09cd\u09a5\u09cd\u09af \u09ac\u09be \u09a8\u09c7\u09b6\u09be\u09a6\u09cd\u09b0\u09ac\u09cd\u09af \u09a8\u09bf\u09af\u09bc\u09c7 \u0995\u09bf\u099b\u09c1\u0987 \u09b0\u09be\u0996\u09c7 \u09a8\u09be, \u09ac\u09b2\u09be \u09b9\u09b2\u09c7\u0993 \u09a8\u09be\u0964"],t.s)
B.bnI=s(["\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a","\u0622\u0646 \u0644\u0627\u0626\u0646 \u0645\u0627\u0688\u0644","\u0985\u09a8\u09b2\u09be\u0987\u09a8 \u09ae\u09a1\u09c7\u09b2"],t.s)
B.b1Y=s(["\u0627\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0641\u064a \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u0627\u0644\u062f\u0639\u0645","\u0633\u067e\u0648\u0631\u0679 \u06af\u0641\u062a\u06af\u0648 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0622\u0646 \u0644\u0627\u0626\u0646 \u0645\u0627\u0688\u0644 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u06cc\u06ba","\u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be \u099a\u09cd\u09af\u09be\u099f\u09c7 \u0985\u09a8\u09b2\u09be\u0987\u09a8 \u09ae\u09a1\u09c7\u09b2 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u0995\u09b0\u09c1\u09a8"],t.s)
B.aZC=s(["\u0645\u062a\u0648\u0642\u0641 \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u064b\u0627. \u064a\u064f\u062c\u0627\u0628 \u0639\u0646 \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u0627\u0644\u062f\u0639\u0645 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632.","\u0628\u0637\u0648\u0631 \u0688\u06cc\u0641\u0627\u0644\u0679 \u0628\u0646\u062f\u06d4 \u0633\u067e\u0648\u0631\u0679 \u06af\u0641\u062a\u06af\u0648 \u06a9\u0627 \u062c\u0648\u0627\u0628 \u0627\u0633\u06cc \u0622\u0644\u06d2 \u067e\u0631 \u062f\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4","\u09a1\u09bf\u09ab\u09b2\u09cd\u099f\u09c7 \u09ac\u09a8\u09cd\u09a7\u0964 \u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be \u099a\u09cd\u09af\u09be\u099f\u09c7\u09b0 \u0989\u09a4\u09cd\u09a4\u09b0 \u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8\u09c7\u0987 \u09a6\u09c7\u0993\u09af\u09bc\u09be \u09b9\u09af\u09bc\u0964"],t.s)
B.b_y=s(["\u0642\u0628\u0644 \u0623\u0646 \u062a\u0641\u0639\u0651\u0644 \u0647\u0630\u0627","\u0627\u0633\u06d2 \u0622\u0646 \u06a9\u0631\u0646\u06d2 \u0633\u06d2 \u067e\u06c1\u0644\u06d2","\u098f\u099f\u09bf \u099a\u09be\u09b2\u09c1 \u0995\u09b0\u09be\u09b0 \u0986\u0997\u09c7"],t.s)
B.bdE=s(["\u0625\u0630\u0627 \u0641\u0639\u0651\u0644\u062a \u0647\u0630\u0627\u060c \u0641\u0642\u062f \u064a\u064f\u0631\u0633\u0644 \u0645\u0627 \u062a\u0643\u062a\u0628\u0647 \u0641\u064a \u0645\u062d\u0627\u062f\u062b\u0629 \u0627\u0644\u062f\u0639\u0645 \u0625\u0644\u0649 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0627\u0644\u0645\u062a\u0635\u0644 \u0628\u0647 \u0627\u0644\u0631\u064a\u0627\u0646 \u0644\u064a\u0643\u062a\u0628 \u0631\u062f\u064b\u0627 \u0623\u0637\u0648\u0644. \u0644\u0627 \u064a\u064f\u0631\u0633\u0644 \u0627\u0633\u0645\u0643\u060c \u0648\u0644\u0627 \u064a\u064f\u0631\u0633\u0644 \u0634\u064a\u0621 \u0625\u0630\u0627 \u0628\u062f\u062a \u0631\u0633\u0627\u0644\u062a\u0643 \u062d\u0627\u0644\u0629 \u0637\u0627\u0631\u0626\u0629 \u0623\u0648 \u0625\u0633\u0627\u0621\u0629 \u0623\u0648 \u0643\u0644\u0627\u0645 \u0637\u0641\u0644. \u0648\u0644\u0627 \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0645\u0641\u062a\u0627\u062d\u0643 \u0627\u0644\u062e\u0627\u0635 \u0644\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0644\u0647\u0630\u0627 \u0627\u0644\u063a\u0631\u0636. \u0648\u0642\u062f \u062a\u062d\u062a\u0641\u0638 \u0634\u0631\u0643\u0629 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0628\u0645\u0627 \u062a\u062a\u0644\u0642\u0627\u0647 \u0644\u0641\u062a\u0631\u0629. \u064a\u0645\u0643\u0646\u0643 \u0625\u064a\u0642\u0627\u0641 \u0647\u0630\u0627 \u0641\u064a \u0623\u064a \u0648\u0642\u062a.","\u0627\u06af\u0631 \u0622\u067e \u0627\u0633\u06d2 \u0622\u0646 \u06a9\u0631\u06cc\u06ba \u062a\u0648 \u0633\u067e\u0648\u0631\u0679 \u06af\u0641\u062a\u06af\u0648 \u0645\u06cc\u06ba \u062c\u0648 \u0622\u067e \u0644\u06a9\u06be\u062a\u06d2 \u06c1\u06cc\u06ba \u0648\u06c1 \u0627\u0633 \u0622\u0646 \u0644\u0627\u0626\u0646 \u0645\u0627\u0688\u0644 \u06a9\u0648 \u0628\u06be\u06cc\u062c\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627 \u06c1\u06d2 \u062c\u0633 \u0633\u06d2 \u0627\u0644\u0631\u06cc\u0627\u0646 \u062c\u0691\u06cc \u06c1\u06d2 \u062a\u0627\u06a9\u06c1 \u0648\u06c1 \u0644\u0645\u0628\u0627 \u062c\u0648\u0627\u0628 \u0644\u06a9\u06be \u0633\u06a9\u06d2\u06d4 \u0622\u067e \u06a9\u0627 \u0646\u0627\u0645 \u0646\u06c1\u06cc\u06ba \u0628\u06be\u06cc\u062c\u0627 \u062c\u0627\u062a\u0627\u060c \u0627\u0648\u0631 \u0627\u06af\u0631 \u0622\u067e \u06a9\u0627 \u067e\u06cc\u063a\u0627\u0645 \u06c1\u0646\u06af\u0627\u0645\u06cc \u0635\u0648\u0631\u062a\u060c \u0632\u06cc\u0627\u062f\u062a\u06cc \u06cc\u0627 \u06a9\u0633\u06cc \u0628\u0686\u06d2 \u06a9\u06cc \u0628\u0627\u062a \u0644\u06af\u06d2 \u062a\u0648 \u06a9\u0686\u06be \u0646\u06c1\u06cc\u06ba \u0628\u06be\u06cc\u062c\u0627 \u062c\u0627\u062a\u0627\u06d4 \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0622\u067e \u06a9\u06cc \u0627\u067e\u0646\u06cc \u0627\u06d2 \u0622\u0626\u06cc \u06a9\u0644\u06cc\u062f \u06a9\u0628\u06be\u06cc \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u06cc\u06d4 \u0645\u0627\u0688\u0644 \u06a9\u0645\u067e\u0646\u06cc \u062c\u0648 \u0648\u0635\u0648\u0644 \u06a9\u0631\u06d2 \u0627\u0633\u06d2 \u06a9\u0686\u06be \u0648\u0642\u062a \u0631\u06a9\u06be \u0633\u06a9\u062a\u06cc \u06c1\u06d2\u06d4 \u0622\u067e \u0627\u0633\u06d2 \u06a9\u0633\u06cc \u0628\u06be\u06cc \u0648\u0642\u062a \u062f\u0648\u0628\u0627\u0631\u06c1 \u0628\u0646\u062f \u06a9\u0631 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u098f\u099f\u09bf \u099a\u09be\u09b2\u09c1 \u0995\u09b0\u09b2\u09c7 \u09b8\u09b9\u09be\u09af\u09bc\u09a4\u09be \u099a\u09cd\u09af\u09be\u099f\u09c7 \u0986\u09aa\u09a8\u09bf \u09af\u09be \u09b2\u09c7\u0996\u09c7\u09a8 \u09a4\u09be \u0986\u09b0-\u09b0\u09be\u0987\u09af\u09bc\u09be\u09a8 \u09af\u09c7 \u0985\u09a8\u09b2\u09be\u0987\u09a8 \u09ae\u09a1\u09c7\u09b2\u09c7\u09b0 \u09b8\u09be\u09a5\u09c7 \u09af\u09c1\u0995\u09cd\u09a4 \u09a4\u09be\u0995\u09c7 \u09aa\u09be\u09a0\u09be\u09a8\u09cb \u09b9\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7, \u09af\u09be\u09a4\u09c7 \u09b8\u09c7 \u09a6\u09c0\u09b0\u09cd\u0998 \u0989\u09a4\u09cd\u09a4\u09b0 \u09b2\u09bf\u0996\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u0964 \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09be\u09ae \u09aa\u09be\u09a0\u09be\u09a8\u09cb \u09b9\u09af\u09bc \u09a8\u09be, \u098f\u09ac\u0982 \u0986\u09aa\u09a8\u09be\u09b0 \u09ac\u09be\u09b0\u09cd\u09a4\u09be \u099c\u09b0\u09c1\u09b0\u09bf \u0985\u09ac\u09b8\u09cd\u09a5\u09be, \u09a8\u09bf\u09b0\u09cd\u09af\u09be\u09a4\u09a8 \u09ac\u09be \u09b6\u09bf\u09b6\u09c1\u09b0 \u0995\u09a5\u09be\u09b0 \u09ae\u09a4\u09cb \u09ae\u09a8\u09c7 \u09b9\u09b2\u09c7 \u0995\u09bf\u099b\u09c1\u0987 \u09aa\u09be\u09a0\u09be\u09a8\u09cb \u09b9\u09af\u09bc \u09a8\u09be\u0964 \u098f\u09b0 \u099c\u09a8\u09cd\u09af \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09bf\u099c\u09c7\u09b0 \u098f\u0986\u0987 \u0995\u09c0 \u0995\u0996\u09a8\u0993 \u09ac\u09cd\u09af\u09ac\u09b9\u09c3\u09a4 \u09b9\u09af\u09bc \u09a8\u09be\u0964 \u09ae\u09a1\u09c7\u09b2 \u0995\u09cb\u09ae\u09cd\u09aa\u09be\u09a8\u09bf \u09af\u09be \u09aa\u09be\u09af\u09bc \u09a4\u09be \u0995\u09bf\u099b\u09c1 \u09b8\u09ae\u09af\u09bc \u09b0\u09be\u0996\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u0964 \u0986\u09aa\u09a8\u09bf \u09af\u09c7\u0995\u09cb\u09a8\u09cb \u09b8\u09ae\u09af\u09bc \u098f\u099f\u09bf \u0986\u09ac\u09be\u09b0 \u09ac\u09a8\u09cd\u09a7 \u0995\u09b0\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u09a8\u0964"],t.s)
B.aPg=s(["\u0623\u0628\u0642\u0647 \u0645\u062a\u0648\u0642\u0641\u064b\u0627","\u0627\u0633\u06d2 \u0628\u0646\u062f \u0631\u06a9\u06be\u06cc\u06ba","\u09ac\u09a8\u09cd\u09a7 \u09b0\u09be\u0996\u09c1\u09a8"],t.s)
